/**
 * Filter chain built from coefficients generated by scipy.
 *
 * The coefficients live in filterCoeffs.json and are produced by
 * pipeline/gen_filter_coeffs.py. Sharing the exact same numbers between the
 * Python reference and this runtime is what makes the offline evaluation
 * meaningful: a hand-designed TS filter of a different order silently changes
 * the detector's behaviour by 20x in the integration stage.
 *
 * Each SOS section is a second-order section in direct form I with its own
 * state, which is what scipy's sosfilt applies.
 */

import coeffs from "./filterCoeffs.json";

export interface Sos {
  b0: number;
  b1: number;
  b2: number;
  a0: number;
  a1: number;
  a2: number;
}

/** Direct-form I second-order section with persistent state. */
export class SosFilter {
  private x1 = 0;
  private x2 = 0;
  private y1 = 0;
  private y2 = 0;
  private readonly c: Sos;

  constructor(section: Sos | Sos[]) {
    this.c = Array.isArray(section) ? (section[0] as Sos) : section;
  }

  process(x: number): number {
    const { b0, b1, b2, a0, a1, a2 } = this.c;
    const y = (b0 * x + b1 * this.x1 + b2 * this.x2 - a1 * this.y1 - a2 * this.y2) / a0;
    this.x2 = this.x1;
    this.x1 = x;
    this.y2 = this.y1;
    this.y1 = y;
    return y;
  }

  reset(): void {
    this.x1 = this.x2 = this.y1 = this.y2 = 0;
  }
}

/** Cascade of SOS sections, equivalent to scipy.signal.sosfilt. */
export class SosCascade {
  readonly sections: SosFilter[];

  constructor(sos: Sos[]) {
    this.sections = sos.map((s) => new SosFilter(s));
  }

  process(x: number): number {
    let y = x;
    for (const s of this.sections) y = s.process(y);
    return y;
  }

  processAll(x: ArrayLike<number>): Float64Array {
    const out = new Float64Array(x.length);
    for (let i = 0; i < x.length; i++) out[i] = this.process(x[i] as number);
    return out;
  }

  reset(): void {
    for (const s of this.sections) s.reset();
  }
}

const C = coeffs as unknown as Record<string, Sos[] | number>;

export const FS: number = C.fs as number;

export const makeQrsFilter = () => new SosCascade(C.qrs as Sos[]);
export const makeWideFilter = () => new SosCascade(C.wide as Sos[]);
/**
 * Low-pass only (40 Hz), for boundary measurement.
 *
 * Deliberately not `wide`: the 0.5 Hz high-pass that makes the display trace
 * stable leaves a long undershoot after every T wave, of order
 * amplitude * sigma / tau, which is larger than the 5%-of-excursion threshold
 * the T offset uses. Baseline removal for delineation is done per wave instead.
 */
export const makeDelineateFilter = () => new SosCascade(C.delineate as Sos[]);
export const makeNotch = (mains: 50 | 60) =>
  new SosCascade(C[mains === 50 ? "notch50" : "notch60"] as Sos[]);

/**
 * Display / measurement chain: notch, then the wide bandpass.
 *
 * The notch is applied only when mains interference is actually present; on
 * this dataset the 50 Hz component is negligible, and notching unconditionally
 * costs a little QRS energy for no benefit.
 */
export class DisplayFilter {
  private notch: SosCascade | null;
  private wide: SosCascade;

  constructor(mains: 50 | 60 | null = null) {
    this.notch = mains === null ? null : makeNotch(mains);
    this.wide = makeWideFilter();
  }

  process(x: number): number {
    const y = this.notch ? this.notch.process(x) : x;
    return this.wide.process(y);
  }

  reset(): void {
    this.notch?.reset();
    this.wide.reset();
  }
}
